@require_POST
def update_integration_endpoint(request, integration_id):
    integration = get_object_or_404(ExternalWebhookIntegration, id=integration_id, organization=request.user.organization)
    integration.target_url = request.POST.get('target_url')
    integration.save(update_fields=['target_url'])
    return JsonResponse({'status': 'updated'})

@receiver(post_save, sender=ExternalWebhookIntegration)
def dispatch_verification_handshake(sender, instance, **kwargs):
    requests.post(instance.target_url, json={'signing_secret': instance.shared_secret})
